  function shareToWhatsapp() {
    var currentInvoiceId = byId("printArea").getAttribute("data-invoice-id");
    var inv = invoices.find(function (x) { return x.id === currentInvoiceId; });
    if (!inv) { toast("لا توجد فاتورة للإرسال", "error"); return; }
    var customer = customers.find(function (c) { return c.id === inv.customerId; });
    if (!customer || !customer.phone) { toast("رقم هاتف العميل غير مسجل", "error"); return; }
    
    var phone = customer.phone.replace(/\D/g, "");
    if (phone.startsWith("0")) phone = phone.substring(1);
    if (!phone.startsWith("966")) phone = "966" + phone;
    
    var text = "*" + business.name + "*\n";
    text += "مرحباً " + customer.name + "،\n";
    text += "تم إصدار فاتورة رقم: *" + inv.number + "*\n";
    text += "التاريخ: " + inv.date + "\n";
    text += "الإجمالي: *" + fmt(inv.grandTotal) + " ر.س*\n\n";
    text += "شكراً لتعاملكم معنا!";
    
    var url = "https://wa.me/" + phone + "?text=" + encodeURIComponent(text);
    window.open(url, "_blank");
  }

